            add_join_split(&mut ts);
        }
        MainTrait::MonotonicCount => {
            add_spec_fn(
                &mut ts,
                "count",
                &Type::Verbatim(quote_vstd! { vstd => #vstd::prelude::nat }),
            );
            add_weaken(&mut ts);
        }
    }
    add_arbitrary(&mut ts);

    quote! {
        #[cfg_attr(verus_keep_ghost, verus::internal(verus_macro))]
        #impl_decl {
            #ts
        }
    }
}

